import * as fs from "fs";
import * as os from "os";
import * as path from "path";

const Dirty = require("../../../../../../../../../../subject_repositories/node-dirty/lib/dirty/dirty.js");

describe("Dirty queued writes", () => {
  it("flushes every write queued while the file stream is applying backpressure", (done) => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "dirty-backpressure-"));
    const dbPath = path.join(dir, "data.db");
    const db = new Dirty(dbPath);
    const completed: string[] = [];

    db.on("load", () => {
      const largeValue = "x".repeat(4 * 1024 * 1024);

      db.set("large", largeValue, (err: Error | null) => {
        if (err) {
          done(err);
          return;
        }

        db.once("drain", () => {
          try {
            expect(completed).toEqual(["queued-1", "queued-2", "queued-3"]);
            db.close();
            done();
          } catch (error) {
            done(error);
          }
        });

        setImmediate(() => {
          db.set("final", "final", (finalErr: Error | null) => {
            if (finalErr) {
              done(finalErr);
            }
          });
        });
      });

      db.set("queued-1", "one", (err: Error | null) => {
        if (err) {
          done(err);
          return;
        }
        completed.push("queued-1");
      });

      db.set("queued-2", "two", (err: Error | null) => {
        if (err) {
          done(err);
          return;
        }
        completed.push("queued-2");
      });

      db.set("queued-3", "three", (err: Error | null) => {
        if (err) {
          done(err);
          return;
        }
        completed.push("queued-3");
      });
    });
  });
});
